#!/usr/bin/env python
""" PyDCviewer - a simple viewer for document cameras
Often document cameras are shipped with some strange piece of blown up software
just to display the picture of the (often quite simple web-)camera. On the other
Hand software like geany is fast and lightweight but lacks some basic functionality
like zooming, panning or rotating the video, that is extremely helpful for
document cameras. This rather simple python script tries to fill this gap.
As it was more or less a proof of concept, it might help others to fullfill similar
tasks using the power of free software and python. Comments, suggestions, ideas
are always welcome.

This program is free software: you can redistribute it and/or modify it under
the terms of the GNU General Public License as published by the Free Software
Foundation, either version 3 of the License, or any later version.

This program is distributed in the hope that it will be useful, but WITHOUT
ANY WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS
FOR A PARTICULAR PURPOSE. See the GNU General Public License for more details.
You should have received a copy of the GNU General Public License along with
this program. If not, see <http://www.gnu.org/licenses/>.
"""

__author__     = "Thomas Schröder"
__contact__    = "dev@bemailt.de"
__copyright__  = "Copyright 2020, Thomas Schröder"
__credits__    = [ "Thomas Schröder", "Christoph Schütz", "openclipart.org" ]
__date__       = "2020/12/14"
__deprecated__ = False
__email__      =  "dev@bemailt.de"
__license__    = "GPL-3.0-or-later"
__maintainer__ = "Thomas Schröder"
__status__     = "Beta"
__version__    = "0.6"

import PySimpleGUI as sg
import cv2
import sys, os
import numpy as np
import base64

# configurable variables
margin_top     = 15                # top margin for buttons
margin_left    = 10                # left margin for the same
width_preview  = 300               # width of the preview window
max_dev        = 4                 # maximum of devices checked (/dev/videoXX)
brightness     = 0                 # standard value for brightness
contrast       = 255               # standard value for contrast
colormode      = 0                 # the actual color mode (0 color, 1 grey, 2 b/w)
zoom_delta     = 0.1               # zoom steps
zoom_max       = 3                 # maximum zoom
pfactor        = 40                # the amount of pixels for manual panning
detect_webcams = True              # enables/disables the webcam-detection (and webcam-choose-window)
img_path       = None              # default image path
img_autosave   = False             # autosave images to img_path (be sure to have write access)
blankrgb       = [255, 255, 255]   # rgb-values for blank screen (b key)
interpolation  = cv2.INTER_NEAREST # one of INTER_NEAREST, INTER_LINEAR, INTER_CUBIC, INTER_LANCZOS4
pan_mode       = 0                 # 0 natural pan, 1 move with mouse, 2 move to direction
txt_pos        = (5,25)            # offset of text elements (added to grid)
txt_color      = 'red'             # color of text elements

# resolutions to be tested (some may break webcam capturing)
testres = [(320,240),(352,240),(352,288),(384,288),(480,360),(640,360),(640,480),(704,480),(720,480),(800,480),(800,600),(960,720),(1024,768),(1280,720),(1280,800),(1280,960),(1280,1024),(1600,1200),(1920,1080),(2048,1536),(2560,2048),(3200,2400),(4096,2160),(4096,3072),(5120,2160),(5120,2880),(5120,3200),(5120,4096),(6400,4096),(6400,4800),(7680,4320),(7680,4800),(10240,4320)]

# a virtual grid for mouse events over the ui - needs to fit ui.png
uigrid = ([ margin_left,
            margin_left +  33,
            margin_left +  66,
            margin_left + 100 ],
          [ margin_top,
            margin_top  +  43,
            margin_top  +  54,
            margin_top  +  97,
            margin_top  + 108,
            margin_top  + 151,
            margin_top  + 162,
            margin_top  + 205,
            margin_top  + 216,
            margin_top  + 259,
            margin_top  + 270,
            margin_top  + 313,
            margin_top  + 325,
            margin_top  + 368,
            margin_top  + 381,
            margin_top  + 425,
            margin_top  + 475,
            margin_top  + 500,
             ])

# internal variables
res_scr = sg.Window.get_screen_size() # get the screen dimensions
mouse_pan    = False                    # mouse: panning mode
mouse_mark   = False                    # mouse: marking mode
mark_rect    = None                     # the rectangle drawn
mark_mode    = False                    # marking mode (to draw rectangles for zoom)
mark_area    = False                    # placeholder for the marked area
show_ui      = True                     # visibility of ui elements
fullscreen   = False                    # used to switch to fullscreen and back
paused       = False                    # (un)pause capture
blanked      = False                    # show blank picture
offset       = (0,0)                    # standard offset (no offset)
zoom         = 1                        # standard zoom for image
img_number   = 0                        # numbering for automatic images
recalculate  = True                    # do calculations (on offset-/zoom-/window-change)
rotation     = 0                        # image rotation (0 no rotation, 1: 90°, 2: 180°, 3: 270°)
blank        = None                     # placeholder for the blank image
lastevent    = None                     # workaround to fetch double mouseclicks


# ui-image as base64-string - much faster and makes it a one-file-script
uipng1 = b''
uipng2 = b''

# german language strings (some are also keys for the event loop)
string_colormode    = [ 'Farbe', 'Grau', 'S/W' ]
string_rotation     = [ '0°', '90°', '180°', '270°' ]
string_help         = 'Hilfe'
string_about        = 'Über PyDCviewer'

error_save          = [ 'Speicherfehler', 'Speicherfehler - bitte die Einstellungen prüfen!' ]
error_nowebcam      = [ 'Webcam-Fehler', 'Keine Webcam gefunden!' ]
error_webcam        = [ 'Webcam-Fehler', 'Fehler beim Öffnen der Webcam!' ]
error_noresolutions = [ 'Webcam-Fehler', 'Keine gültigen Auflösungen gefunden!' ]

button_ok           = 'Übernehmen'
button_cancel       = 'Abbrechen'
button_saveimageas  = 'Bild speichern unter...'

text_help           = 'Befehlsübersicht:\n\nMit gedrückter linker Maustaste und den Pfeiltasten kann das Bild verschoben werden.\nDas Mausrad kann zum Zoomen genutzt werden.\n\n+ - Vergrößern um '+str(zoom_delta)+'.\n# - Zoom auf 1 setzen\n- - Verkleinern um '+str(zoom_delta)+'.\nr - Bild drehen (90°)p - Bild einfrieren\nf - Vollbild\nu - Bedienfenster aus-/einblenden\nb - Farbvorhang\nm - Auswahlrechteckmodus\ns - Bild speichern\n\nF1 - Diese Hilfe :-)'
text_about          = 'PyDCviewer ist ein einfacher Viewer für Dokumentenkameras. Es bietet einige grundlegende Funktionen zur Bildveränderung, die beim Einsatz einer Dokumentenkamera hilfreich sind.\n\nPyDCviewer ist Freie Software: Sie können es unter den Bedingungen der GNU General Public License, wie von der Free Software Foundation, Version 3 der Lizenz oder jeder neueren veröffentlichten Version, weiter verteilen und/oder modifizieren (vgl. <https://www.gnu.org/licenses/>).'

sg.theme('DarkAmber') # why not...

# part 1: detect webcam and select resolution
if len(sys.argv) == 2:
    cap = cv2.VideoCapture(int(sys.argv[1]))
    res_cap =  int(cap.get(3)), int(cap.get(4))
elif detect_webcams:
    startup = True
    
    # cam-/resolution-chooser
    camradios = [[ sg.Radio('Webcam 1', "webcam", key='0', enable_events=True, default=True, size=(10,1)) ],
                 [ sg.Radio('Webcam 2', "webcam", key='1', enable_events=True, visible=False) ],
                 [ sg.Radio('Webcam 3', "webcam", key='2', enable_events=True, visible=False) ],
                 [ sg.Radio('Webcam 4', "webcam", key='3', enable_events=True, visible=False) ],
                 [ sg.Radio('Webcam 5', "webcam", key='4', enable_events=True, visible=False) ],
                 [ sg.Radio('Webcam 6', "webcam", key='5', enable_events=True, visible=False) ],
                 [ sg.Radio('Webcam 7', "webcam", key='6', enable_events=True, visible=False) ],
                 [ sg.Radio('Webcam 8', "webcam", key='7', enable_events=True, visible=False) ]]
    preview =   [[ sg.Image( size=(width_preview, 1), key='preview', metadata=None) ],
                 [ sg.Combo([], size=(20,1), enable_events=True, readonly=True, visible=False, key='resolutions') ]]

    layout =   [[ sg.Column(camradios, key='col_camradios'),
                  sg.Column(preview,   key='col_preview') ],
                [ sg.Button(button_ok), sg.Button(button_cancel) ] ]

    camchoose = sg.Window('PyDocuCamViewer', layout, return_keyboard_events=True).finalize()
    
    # detect webcams
    webcams = []
    for index in range(0,max_dev):
        cap = cv2.VideoCapture(index)
        if cap.read()[0]:
            webcams.append(index)
        cap.release()

    if not len(webcams) > 0:
        sg.popup(error_nowebcam[1], title=error_nowebcam[0], keep_on_top=True)
        sys.exit('no webcam found')

    for c in webcams:
        camchoose[str(c)].Update(visible=True)

    while True:
        event, values = camchoose.read(timeout=20)
        
        if startup or event in ['1', '2', '3', '4', '5', '6', '7', '8']:
            # find resolutions, change device
            if startup:
                # at startup choose first device
                device = webcams[0]
                startup = False
            else:
                device = int(event)
                cap.release()
            
            cap = cv2.VideoCapture(device)
            workingres = []
            for x,y in testres:
                cap.set(3, x)
                cap.set(4, y)
                res_cap = int(cap.get(3)), int(cap.get(4))
                # workaround for corvusalbus ;-) needs to be tested on different systems
                if not all(res_cap):
                    res_cap = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH)), int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
                if all(res_cap):
                    workingres.append(res_cap)
            if len(workingres) == 0:
                sg.popup(error_noresolutions[1], title=error_noresolutions[0], keep_on_top=True)
                sys.exit('no valid resolutions')
            # find max working resolution
            resolutions = sorted(workingres, key = lambda i : i[0], reverse = True)
            # workaround (something seems to get broken from tests with strange resolutions sometimes)
            cap.release()
            cap = cv2.VideoCapture(device)
            cap.set(3, resolutions[0][0])
            cap.set(4, resolutions[0][1])
            res_cap = resolutions[0]
            
            # fill in resolutions-combo
            camchoose['resolutions'].update(values=resolutions, set_to_index=0)

        if event == 'resolutions':
            # save the resolution
            res_cap = values['resolutions']
            # set the resolution
            cap.set(3, res_cap[0])
            cap.set(4, res_cap[1])
            
        if event == sg.WIN_CLOSED or event == 'Escape:9' or event == button_cancel: # if user closes window or clicks cancel
            camchoose.close()
            sys.exit()
        if event == button_ok:
            break

        ret, frame = cap.read()
        
        # resize frame for preview window
        zfactor = width_preview/cap.get(3)
        frame = cv2.resize(frame, None, fx=zfactor, fy=zfactor, interpolation = cv2.INTER_CUBIC)
        camchoose['preview'].update(data=cv2.imencode('.png', frame)[1].tobytes())
        camchoose['resolutions'].update(visible=True)
  
    camchoose.close()
else:
    # try first webcam
    cap = cv2.VideoCapture(0)
    res_cap =  int(cap.get(3)), int(cap.get(4))

if not cap or not all(res_cap):
    sg.popup(error_webcam[1], title=error_webcam[0], keep_on_top=True)
    sys.exit('Webcam Error')
            
# part 2: webcam is now available as cap, resolution as res_cap (both won't be changed)

# create layout (use res_cap as initial size)
res_win      = res_cap    # the size of the window
res_capc     = res_cap    # the corrected resolution for the capturing device (needed for rotation)

layout = [[ sg.Graph(canvas_size=(res_win), graph_bottom_left=(0, res_win[1]), graph_top_right=(res_win[0], 0), key="image", enable_events=True, change_submits=True, drag_submits=True) ]]
window = sg.Window('PyDocuCamViewer', layout, location=(50, 50), return_keyboard_events=True, size=res_win, resizable=True, element_padding=(0,0), margins=(0,0), border_depth=0).finalize()

# the main event loop
while True:
    res_wina = window.size
    if res_win != res_wina:
        # resize image graph
        res_win = window.size
        window['image'].set_size(res_win)
        recalculate = True

    # A. event processing
    event, values = window.read(timeout = 10)  # in case of problems try 0 / 20 / 80
    if event == lastevent and event.endswith('+UP'):
        continue
    lastevent = event
    
    # left for debugging
    # ~ if event != '__TIMEOUT__':
        # ~ print(event)
    
    # A1. mouse - events
    if event.startswith("image"):
        x, y = values["image"]
        
        if mouse_mark:
            # avoid 0/negative rectangles in mark mode
            if x < mouse_mx:
                x = mouse_mx
            if y < mouse_my:
                y = mouse_my
            # ~ # resize rect to minimum size for max_zoom
            # ~ if mouse_mx-x < zoom * res_capc[0] / zoom_max:
                # ~ x += int(zoom*res_capc[0] / zoom_max)
            # ~ if mouse_my-y < zoom*res_capc[1] / zoom_max:
                # ~ y += int(zoom*res_capc[1] / zoom_max)
            
        # ui and gridclick -> button
        gridx = -1
        for testx in uigrid[0]:
            if x > testx:
                gridx += 1
        gridy = -1
        for testy in uigrid[1]:
            if y > testy:
                gridy += 1
        if gridx+1 == len(uigrid[0]) or gridy+1 == len(uigrid[1]):
            gridclick = False
        else:
            gridclick = (gridx, gridy)
        if show_ui and gridclick != False and event.endswith('+UP'):
            # check the different buttons
            # brightness
            if gridclick == (0, 0):
                brightness -= 10
            elif gridclick == (1, 0):
                brightness = 0
            elif gridclick == (2, 0):
                brightness += 10
            # contrast
            elif gridclick == (0, 2):
                contrast -= 10
            elif gridclick == (1, 2):
                contrast = 255
            elif gridclick == (2, 2):
                contrast += 10
            # zoom
            elif gridclick == (0, 4):
                event = 'zoomout'
            elif gridclick == (1, 4):
                event = 'zoomreset'
            elif gridclick == (2, 4):
                event = 'zoomin'
            # rotation
            elif gridclick == (0, 6):
                if rotation > 0:
                    rotation -= 1
                else:
                    rotation = 3
                recalculate = True
            elif gridclick == (1, 6):
                rotation = 0
                recalculate = True
            elif gridclick == (2, 6):
                if rotation < 3:
                    rotation += 1
                else:
                    rotation = 0
                recalculate = True
            # colormodes
            elif gridclick == (0, 8):
                colormode = 0
            elif gridclick == (1, 8):
                colormode = 1
            elif gridclick == (2, 8):
                colormode = 2    
            # zoom by rect
            elif gridclick[1] == 10:
                event = 'm:58'
            # fullscreen, save, help    
            elif gridclick == (0, 12):
                event = 'f:41'
            elif gridclick == (1, 12):
                event = 's:39'
            elif gridclick == (2, 12):
                event = 'F1:67'
            # exit
            elif gridclick[1] == 14:
                event = 'Escape:9'
            
            # hide ui
            elif gridclick == (0, 16):
                event = 'u:30'
            else:
                gridclick = False
        # show ui again
        elif not show_ui and event.endswith('+UP') and gridclick == (0,16):
            event = 'u:30'

        # no-button, click (down)
        elif gridclick == False and not event.endswith('+UP'):
            # mark_mode True -> start mouse_mark
            if mark_mode:
                if not mouse_mark:
                    mouse_pan  = False
                    mouse_mark = True
                    mouse_mx   = x
                    mouse_my   = y
                else:
                    # keep the aspect ration of the window
                    mark_area = ((mouse_mx, mouse_my), (x, int(mouse_my+(x-mouse_mx)*ar_win)))
            # otherwise mouse-pan
            elif not mark_mode:
                # start mouse_pan
                if not mouse_pan:
                    if pan_mode in (0, 1):
                        old_offset = offset
                    mouse_pan  = True
                    mouse_mark = False
                    mouse_uix  = x
                    mouse_uiy  = y
                # change image offset by mouse movement
                else:
                    if pan_mode == 0:
                        offset = (old_offset[0]-int((x-mouse_uix)/(zoom)), old_offset[1]-int((y-mouse_uiy)/(zoom)))
                    elif pan_mode == 1:
                        offset = (old_offset[0]+int((x-mouse_uix)/(zoom)), old_offset[1]+int((y-mouse_uiy)/(zoom)))
                    else:
                        offset = (offset[0]+x-mouse_uix, offset[1]+y-mouse_uiy)
                    recalculate = True
        elif gridclick == False and event.endswith('+UP'):
            # mark_mode true -> end of mouse_mark
            if mark_mode:
                # do not allow 0-size-rects
                if not (mouse_mx == x or mouse_my == y):
                    recalculate = True
                mark_mode = False
                mouse_mark = False
                window['image'].set_cursor(cursor='arrow')
            # end pan
            else:
                mouse_pan = False
    
    # A2. keyboard-events
    if event == 'f:41':                                                 # f: fullscreen
        fullscreen = not fullscreen
        recalculate = True
    elif event == 'u:30':                                               # u: show/hide ui elements
        show_ui = not show_ui
    elif event == 'r:27':                                               # r: rotate the image
        if rotation < 3:
            rotation += 1
        else:
            rotation = 0
        recalculate = True
    elif event == 'm:58':                                               # m: mark area for zoom
        # change cursor
        if not mark_mode:
            window['image'].set_cursor(cursor='cross')
        else:
            window['image'].set_cursor(cursor='arrow')
        mark_mode = not mark_mode
    elif event == 's:39':                                               # s: save frame to file
        if img_autosave:
            imagepath = os.path.join(img_path,'pydcviewer_'+str("{0:0=3d}".format(img_number))+'.png')
            img_number += 1
        else:
            imagepath = sg.PopupGetFile(button_saveimageas, title=None, default_path=img_path, save_as=True, default_extension='.png', keep_on_top=True, modal=True)
        try:
            if not (imagepath.endswith('.png') or imagepath.endswith('.PNG')):
                imagepath += '.png'
            cv2.imwrite(imagepath, frame)
        except:
            sg.popup(error_save[1], title=error_save[0], keep_on_top=True)
    elif event == 'p:33':                                               # p: pause picture
        paused = not paused
    elif event == 'b:56':                                               # b: blank picture
        if not blanked:
            blanked_ui = show_ui
            show_ui = False
        elif blanked:
            show_ui = blanked_ui
        blanked = not blanked
    elif event == 'F1:67':                                              # F1: get some help
        sg.popup(text_help, title= string_help, keep_on_top=True)
    elif event == 'F2:68':                                              # F2: get some informations
        sg.popup(text_about, title= string_about, keep_on_top=True)
    elif event == 'Escape:9' or event == sg.WIN_CLOSED:                 # ESC: exit
            break
    elif event == 'plus:35' or event == 'zoomin' or event == 'MouseWheel:Up': # +,-,#: zoom events
        if zoom <= zoom_max-zoom_delta:
            deltaoffset = (int((res_capc[0]/zoom-res_capc[0]/(zoom+zoom_delta)) / 2), int((res_capc[1]/zoom-res_capc[1]/(zoom+zoom_delta)) / 2))
            offset = (offset[0] + deltaoffset[0], offset[1] + deltaoffset[1])
            zoom = round(zoom + zoom_delta, 1)
        recalculate = True
    elif event == 'minus:61' or event == 'zoomout' or event == 'MouseWheel:Down':
        if zoom >= zoom_delta:
            deltaoffset = (int((res_capc[0]/(zoom-zoom_delta)-res_capc[0]/zoom) / 2), int((res_capc[1]/(zoom-zoom_delta)-res_capc[1]/zoom) / 2))
            offset = (offset[0] - deltaoffset[0], offset[1] - deltaoffset[1]) 
            zoom = round(zoom - zoom_delta, 1)
        recalculate = True
    elif event == 'numbersign:51' or event == 'zoomreset':
        zoom = 1
        offset = (0,0)
        recalculate = True
    elif event == 'Right:114':                                          # arrows: offset events
        offset = (offset[0] + pfactor, offset[1])
        recalculate = True
    elif event == 'Left:113':
        offset = (offset[0] - pfactor, offset[1])
        recalculate = True
    elif event == 'Down:116':
        offset = (offset[0], offset[1] + pfactor)
        recalculate = True
    elif event == 'Up:111':
        offset = (offset[0], offset[1] - pfactor)
        recalculate = True
    
    # B. frame capture and manipulation
    if not (paused or blanked):
        ret, frame = cap.read()
        #cap.set(cv2.CAP_PROP_FPS, 30); # read this somewhere...
        
        # adjust rotation
        if rotation == 0:
            res_capc = res_cap
        elif rotation == 1:
            frame = cv2.rotate(frame, cv2.ROTATE_90_CLOCKWISE)
            res_capc = res_cap[1], res_cap[0]
        elif rotation == 2:
            frame = cv2.rotate(frame, cv2.ROTATE_180)
            res_capc = res_cap
        elif rotation == 3:
            frame = cv2.rotate(frame, cv2.ROTATE_90_COUNTERCLOCKWISE)
            res_capc = res_cap[1], res_cap[0]
        
        # adjust brightness and contrast
        b = brightness
        c = contrast
        alpha = b
        beta = b+c
        cv2.normalize(frame, frame, alpha, beta, cv2.NORM_MINMAX)

        # adjust color mode
        if colormode == 1:
            frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        elif colormode == 2:
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            (thresh, frame) = cv2.threshold(gray, 127, 255, cv2.THRESH_BINARY)
        
        # calculate zoom-factor from rect in mark_mode (needed twice)
        if mark_mode and mark_area:
            mark_zoom = round(res_view[0]*zoom/(mark_area[1][0]-mark_area[0][0]),1)
        
        # fit res_view into res_cap as big as possible with same proportions as res_win
        if recalculate:
            ar_cap    = res_capc[1]/res_capc[0]
            ar_win    = res_win[1]/res_win[0]
            ar_wininv = res_win[0]/res_win[1]

            if ar_win < ar_cap:
                res_view = (res_capc[0], ar_win * res_capc[0])
            else:
                res_view = (ar_wininv * res_capc[1], res_capc[1])

            # new offset-/zoom-values if marked by rectangle
            if mark_area:
                # remap coordinates to res_capc
                offset = ( int(offset[0] + (mark_area[0][0]/res_win[0])*res_view[0]), int(offset[1] + (mark_area[0][1]/res_win[1])*res_view[1]) )
                # calculate zoom-factor from x-values
                zoom = mark_zoom
                mark_area = None

            # correct zoom
            if zoom < 1:
                zoom = 1
            if zoom > zoom_max:
                zoom = zoom_max

            # zoom to viewframe (scale res_view)
            res_view = (int(res_view[0]/zoom), int(res_view[1]/zoom))
            
            # correct offset
            if offset[0] < 0:
                offset = (0, offset[1])
            if offset[1] < 0:
                offset = (offset[0], 0)
            if offset[0] + res_view[0] > res_capc[0]:
                offset = (res_capc[0] - res_view[0], offset[1])
            if offset[1] + res_view[1] > res_capc[1]:
                offset = (offset[0], res_capc[1] - res_view[1])
            
            blank = np.uint8(np.absolute(blankrgb * np.ones((res_win[1], res_win[0], 3), np.uint8)))
                
            recalculate = False
        # extract viewframe at offset
        frame = frame[offset[1]:offset[1]+res_view[1], offset[0]:offset[0]+res_view[0]]
    
        # scale up viewframe to window dimensions
        frame = cv2.resize(frame, res_win, interpolation = interpolation) #cv2.INTER_CUBIC)
       
    # show the (precalculated) blank frame if blanked
    elif blanked:
        frame = blank
  
    # erase canvas
    window['image'].Erase()

    # change fullscreen visibility
    if fullscreen and not window.maximized:
        window.maximize()
    elif not fullscreen and window.maximized:
        window.normal()
    
    # draw image and ui
    window['image'].DrawImage(data=cv2.imencode('.png', frame)[1].tobytes(), location=(0,0))

    if show_ui:
        window['image'].DrawImage(data=uipng1, location=((margin_left,margin_top)))
        # write info text
        window['image'].DrawText(str((brightness) // 10), (uigrid[0][3]+txt_pos[0], uigrid[1][0]+txt_pos[1]), color=txt_color, text_location=sg.TEXT_LOCATION_LEFT)
        window['image'].DrawText(str((contrast-255) // 10), (uigrid[0][3]+txt_pos[0], uigrid[1][2]+txt_pos[1]), color=txt_color, text_location=sg.TEXT_LOCATION_LEFT)
        window['image'].DrawText(str(zoom), (uigrid[0][3]+txt_pos[0], uigrid[1][4]+txt_pos[1]), color=txt_color, text_location=sg.TEXT_LOCATION_LEFT)
        window['image'].DrawText(string_rotation[rotation], (uigrid[0][3]+txt_pos[0], uigrid[1][6]+txt_pos[1]), color=txt_color, text_location=sg.TEXT_LOCATION_LEFT)
        window['image'].DrawText(string_colormode[colormode], (uigrid[0][3]+txt_pos[0], uigrid[1][8]+txt_pos[1]), color=txt_color, text_location=sg.TEXT_LOCATION_LEFT)
    else:
        window['image'].DrawImage(data=uipng2, location=((margin_left,margin_top)))
    if mark_mode and mouse_mark and mark_area:
        mark_rect = window['image'].DrawRectangle(mark_area[0], mark_area[1], line_color="red")
        window['image'].DrawText(str(mark_zoom), (mark_area[1][0]+txt_pos[0], mark_area[1][1]+txt_pos[1]), color=txt_color, text_location=sg.TEXT_LOCATION_LEFT)
